const base = new URL(self.registration.scope);
const absolute = path => new URL(path, base).href;
const mediaKey = file => absolute(file.url) + '?revision=' + file.hash;
const mediaByPath = new Map(MEDIA_FILES.map(file => [new URL(file.url, base).pathname, file]));
let mediaJob = null;

async function report(phase, done=0, total=0) {
  const message = {type:'shuffle-offline', phase, done, total};
  for (const client of await self.clients.matchAll({type:'window', includeUncontrolled:true})) client.postMessage(message);
}

async function verified(response, hash) {
  if (!response || !response.ok) throw Error('File unavailable');
  const bytes = await response.clone().arrayBuffer();
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  const actual = Array.from(new Uint8Array(digest), n => n.toString(16).padStart(2,'0')).join('');
  if (actual !== hash) throw Error('File does not match this app version');
  return response;
}

async function prepareCore() {
  const cache = await caches.open(CORE_CACHE);
  let done = 0;
  await report('core-preparing', done, CORE_FILES.length);
  for (const file of CORE_FILES) {
    if (!await cache.match(absolute(file.url))) {
      const response = await verified(await fetch(new Request(absolute(file.url), {cache:'reload'})), file.hash);
      await cache.put(absolute(file.url), response);
    }
    await report('core-preparing', ++done, CORE_FILES.length);
  }
  await report('core-ready', done, CORE_FILES.length);
}

async function legacyNames() {
  return (await caches.keys()).filter(name => name.startsWith('shuffle-offline-'));
}

// Once this worker activates, the old app windows have closed. Move each
// verified image individually: a successful put always precedes the old delete.
async function migrateLegacyImages() {
  const names = await legacyNames();
  if (!names.length) return;
  const target = await caches.open(MEDIA_CACHE);
  const old = await Promise.all(names.map(name => caches.open(name)));
  let done = 0, failed = false;
  for (const file of MEDIA_FILES) {
    try {
      if (!await target.match(mediaKey(file))) {
        for (const source of old) {
          const hit = await source.match(absolute(file.url));
          if (!hit) continue;
          try { await verified(hit, file.hash); } catch { continue; }
          await target.put(mediaKey(file), hit);
          break;
        }
      }
      if (await target.match(mediaKey(file))) {
        for (const source of old) await source.delete(absolute(file.url));
      }
    } catch { failed = true; break; }
    if (++done % 50 === 0) await report('media-migrating', done, MEDIA_FILES.length);
  }
  if (!failed) for (const name of names) await caches.delete(name);
  // A quota failure retains remaining legacy entries for verified fallback.
  if (failed) await report('media-failed');
}

async function getImage(file, persistRequired=false) {
  const cache = await caches.open(MEDIA_CACHE);
  const key = mediaKey(file), hit = await cache.match(key);
  if (hit) return hit;
  let response, oldSource;
  for (const name of await legacyNames()) {
    const source = await caches.open(name), candidate = await source.match(absolute(file.url));
    if (!candidate) continue;
    try { response = await verified(candidate, file.hash); oldSource = source; break; } catch {}
  }
  if (!response) response = await verified(await fetch(absolute(file.url)), file.hash);
  try {
    await cache.put(key, response.clone());
    if (oldSource) await oldSource.delete(absolute(file.url));
  } catch (error) {
    if (persistRequired) throw error;
    await report('media-failed');
  }
  return response;
}

async function mediaCount() {
  const cache = await caches.open(MEDIA_CACHE);
  const stored = new Set((await cache.keys()).map(request => request.url));
  return MEDIA_FILES.filter(file => stored.has(mediaKey(file))).length;
}

async function status() {
  const cache = await caches.open(CORE_CACHE);
  const results = await Promise.all(CORE_FILES.map(file => cache.match(absolute(file.url))));
  await report(results.every(Boolean) ? 'core-ready' : 'core-failed');
  await report(mediaJob ? 'media-preparing' : 'media-status', await mediaCount(), MEDIA_FILES.length);
}

async function prepareImages() {
  try {
    const cache = await caches.open(MEDIA_CACHE);
    const missing = [];
    for (const file of MEDIA_FILES) if (!await cache.match(mediaKey(file))) missing.push(file);
    let done = MEDIA_FILES.length - missing.length;
    await report('media-preparing', done, MEDIA_FILES.length);
    for (let start=0; start<missing.length; start+=4) {
      const results = await Promise.allSettled(missing.slice(start,start+4).map(file => getImage(file,true)));
      done += results.filter(result => result.status === 'fulfilled').length;
      await report('media-preparing', done, MEDIA_FILES.length);
      if (results.some(result => result.status === 'rejected')) throw Error('Image preparation failed');
    }
    for (const name of await legacyNames()) await caches.delete(name);
    await report('media-ready', MEDIA_FILES.length, MEDIA_FILES.length);
  } catch { await report('media-failed', await mediaCount(), MEDIA_FILES.length); }
}

self.addEventListener('install', event => event.waitUntil((async () => {
  try { await prepareCore(); }
  catch (error) { await caches.delete(CORE_CACHE); await report('core-failed'); throw error; }
})()));

// No skipWaiting: switching versions never interrupts an editing session.
self.addEventListener('activate', event => event.waitUntil((async () => {
  await migrateLegacyImages();
  const media = await caches.open(MEDIA_CACHE);
  const wanted = new Set(MEDIA_FILES.map(mediaKey));
  for (const request of await media.keys()) if (!wanted.has(request.url)) await media.delete(request);
  for (const name of await caches.keys()) if (name.startsWith('shuffle-core-') && name !== CORE_CACHE) await caches.delete(name);
  await self.clients.claim();
  await status();
})()));

self.addEventListener('message', event => {
  if (!event.source || !event.source.url || new URL(event.source.url).origin !== base.origin) return;
  if (event.data?.type === 'SHUFFLE_OFFLINE_STATUS') event.waitUntil(status().catch(() => report('core-failed')));
  if (event.data?.type === 'SHUFFLE_PREPARE_CORE') event.waitUntil(prepareCore().catch(() => report('core-failed')));
  if (event.data?.type === 'SHUFFLE_PREPARE_IMAGES') {
    if (!mediaJob) mediaJob = prepareImages().finally(() => { mediaJob = null; });
    event.waitUntil(mediaJob);
  }
});

self.addEventListener('fetch', event => {
  const request = event.request, url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== base.origin) return;
  const image = mediaByPath.get(url.pathname);
  const path = request.mode === 'navigate' && (url.pathname === base.pathname || url.pathname === new URL('index.html',base).pathname) ? './index.html' : CORE_FILES.find(file => new URL(file.url,base).pathname === url.pathname)?.url;
  if (!image && !path) return;
  event.respondWith((async () => {
    try {
      if (image) return await getImage(image);
      const cache = await caches.open(CORE_CACHE), hit = await cache.match(absolute(path));
      if (hit) return hit;
      const file = CORE_FILES.find(file => file.url === path);
      const response = await verified(await fetch(new Request(absolute(path),{cache:'reload'})), file.hash);
      try { await cache.put(absolute(path),response.clone()); } catch { await report('core-failed'); }
      return response;
    } catch {
      return new Response('This offline file is unavailable. Reconnect and open Offline & install to prepare it again.', {status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}});
    }
  })());
});
